func registerFrontier(reg *generator.Registry) {
	reg.Register("em.frontier.solver_as_tool", &edakit.Bank{Items: solverToolItems})
	reg.Register("em.frontier.fast_accurate_modes", &edakit.Bank{Items: fastAccurateItems})
	reg.Register("em.frontier.calibration_tier", &edakit.Bank{Items: calibrationItems})
	reg.Register("em.frontier.differential_check", &edakit.Bank{Items: differentialItems})
	reg.Register("em.frontier.tool_grounded_reward", &edakit.Bank{Items: rewardItems})
}

